import sys
import json


def solve(request):
    ebits = request["ebits"]
    fbits = request["fbits"]
    mode = request["mode"]
    pairs = request["pairs"]

    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits
    Eall = (1 << ebits) - 1
    emin = 1 - bias
    emax = Eall - 1 - bias
    fmask = F - 1
    w = 1 + ebits + fbits
    sbit = 1 << (w - 1)
    topf = 1 << (fbits - 1)

    any_nan = False
    invalid = False
    inf_mask = 0          # bit0: a +inf product seen; bit1: a -inf product seen
    terms = []            # (sign, significand, exponent) of nonzero finite products
    any_product = False
    all_neg_zero = True
    min_p = 0
    have_p = False

    for pair in pairs:
        va = int(pair[0], 16)
        vb = int(pair[1], 16)
        ea = (va >> fbits) & Eall
        fa = va & fmask
        eb = (vb >> fbits) & Eall
        fb = vb & fmask

        # inspect every operand for signaling NaN
        if ea == Eall and 0 < fa < topf:
            invalid = True
        if eb == Eall and 0 < fb < topf:
            invalid = True

        a_nan = ea == Eall and fa != 0
        b_nan = eb == Eall and fb != 0
        if a_nan or b_nan:
            any_nan = True
            continue

        sa = va >> (w - 1)
        sb = vb >> (w - 1)
        sign = sa ^ sb
        a_inf = ea == Eall
        b_inf = eb == Eall
        if a_inf or b_inf:
            a_zero = ea == 0 and fa == 0
            b_zero = eb == 0 and fb == 0
            if (a_inf and b_zero) or (b_inf and a_zero):
                invalid = True
            else:
                inf_mask |= 1 << sign
            continue

        # finite x finite
        any_product = True
        if ea == 0:
            ma = fa
            pa = 1 - bias - fbits
        else:
            ma = F + fa
            pa = ea - bias - fbits
        if eb == 0:
            mb = fb
            pb = 1 - bias - fbits
        else:
            mb = F + fb
            pb = eb - bias - fbits
        m = ma * mb
        if m == 0:
            if sign == 0:
                all_neg_zero = False
        else:
            all_neg_zero = False
            p = pa + pb
            terms.append((sign, m, p))
            if not have_p or p < min_p:
                min_p = p
                have_p = True

    if inf_mask == 3:
        invalid = True

    if any_nan or invalid:
        canon = (Eall << fbits) | topf
        return {"bits": format(canon, "x"),
                "flags": ["invalid"] if invalid else []}

    if inf_mask:
        s = 1 if inf_mask == 2 else 0
        return {"bits": format((s << (w - 1)) | (Eall << fbits), "x"),
                "flags": []}

    # exact finite accumulation: S * 2**min_p
    S = 0
    B = min_p if have_p else 0
    for sign, m, p in terms:
        t = m << (p - B)
        S = S - t if sign else S + t

    if S == 0:
        neg = (any_product and all_neg_zero) or mode == "RDN"
        return {"bits": format(sbit if neg else 0, "x"), "flags": []}

    sgn = 1 if S < 0 else 0
    A = -S if sgn else S
    L = A.bit_length() - 1 + B
    q_exp = L - fbits
    if emin - fbits > q_exp:
        q_exp = emin - fbits

    # round x / 2**q_exp to an integer, x = A * 2**B
    shift = q_exp - B
    inexact = False
    if shift <= 0:
        y_int = A << (-shift)
    else:
        n = A >> shift
        r = A - (n << shift)
        if r:
            inexact = True
            if mode == "RNE":
                half = 1 << (shift - 1)
                if r > half or (r == half and (n & 1)):
                    n += 1
            elif mode == "RNA":
                if r >= (1 << (shift - 1)):
                    n += 1
            elif mode == "RUP":
                if sgn == 0:
                    n += 1
            elif mode == "RDN":
                if sgn == 1:
                    n += 1
            # RTZ: truncate
        y_int = n

    # overflow of the rounded magnitude?
    if y_int != 0 and q_exp + y_int.bit_length() - 1 >= emax + 1:
        if (mode == "RNE" or mode == "RNA"
                or (mode == "RUP" and sgn == 0)
                or (mode == "RDN" and sgn == 1)):
            bits = (sgn << (w - 1)) | (Eall << fbits)
        else:
            bits = (sgn << (w - 1)) | ((Eall - 1) << fbits) | fmask
        return {"bits": format(bits, "x"), "flags": ["overflow", "inexact"]}

    flags = []
    if inexact:
        d = emin - q_exp
        if d >= 0:
            tiny = y_int < (1 << d)
        else:
            tiny = y_int == 0
        if tiny:
            flags.append("underflow")
        flags.append("inexact")

    if y_int == 0:
        bits = sgn << (w - 1)
    else:
        k = y_int.bit_length() - 1
        Lp = q_exp + k
        if Lp >= emin:
            e_field = Lp + bias
            if k >= fbits:
                sig = y_int >> (k - fbits)
            else:
                sig = y_int << (fbits - k)
            bits = (sgn << (w - 1)) | (e_field << fbits) | (sig & fmask)
        else:
            bits = (sgn << (w - 1)) | y_int
    return {"bits": format(bits, "x"), "flags": flags}


def main():
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        out.write(json.dumps(solve(json.loads(line))))
        out.write("\n")


if __name__ == "__main__":
    main()
