"""Independent reference implementation using exact Fractions (for testing)."""
from fractions import Fraction

def _ge_pow2(x, e):
    """Fraction x >= 2**e ?"""
    if e >= 0:
        return x.numerator >= (x.denominator << e)
    return (x.numerator << (-e)) >= x.denominator

def _floorlog2(x):
    L = x.numerator.bit_length() - x.denominator.bit_length()
    while not _ge_pow2(x, L):
        L -= 1
    while _ge_pow2(x, L + 1):
        L += 1
    return L

def ref_solve(req):
    ebits, fbits, mode, pairs = req["ebits"], req["fbits"], req["mode"], req["pairs"]
    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits
    Eall = (1 << ebits) - 1
    emin = 1 - bias
    emax = Eall - 1 - bias
    w = 1 + ebits + fbits
    fmask = F - 1

    def decode(h):
        v = int(h, 16)
        s = v >> (w - 1)
        e = (v >> fbits) & Eall
        f = v & fmask
        if e == Eall:
            if f == 0:
                return ('inf', s)
            return ('snan' if (f >> (fbits - 1)) == 0 else 'qnan', s)
        if e == 0:
            if f == 0:
                return ('zero', s)
            return ('fin', s, Fraction(f) * Fraction(2) ** (1 - bias - fbits))
        return ('fin', s, Fraction(F + f) * Fraction(2) ** (e - bias - fbits))

    invalid = False
    any_nan = False
    inf_signs = set()
    total = Fraction(0)
    any_product = False
    all_neg_zero = True

    for p in pairs:
        for h in p:
            if decode(h)[0] == 'snan':
                invalid = True

    for p in pairs:
        a = decode(p[0])
        b = decode(p[1])
        if a[0] in ('snan', 'qnan') or b[0] in ('snan', 'qnan'):
            any_nan = True
            continue
        sign = a[1] ^ b[1]
        if a[0] == 'inf' or b[0] == 'inf':
            if a[0] == 'zero' or b[0] == 'zero':
                invalid = True
            else:
                inf_signs.add(sign)
            continue
        any_product = True
        if a[0] == 'zero' or b[0] == 'zero':
            if sign == 0:
                all_neg_zero = False
        else:
            all_neg_zero = False
            va = a[2] if a[1] == 0 else -a[2]
            vb = b[2] if b[1] == 0 else -b[2]
            total += va * vb

    if len(inf_signs) == 2:
        invalid = True

    canon = (Eall << fbits) | (1 << (fbits - 1))
    if any_nan or invalid:
        return {"bits": format(canon, 'x'),
                "flags": ["invalid"] if invalid else []}
    if inf_signs:
        s = next(iter(inf_signs))
        return {"bits": format((s << (w - 1)) | (Eall << fbits), 'x'), "flags": []}

    if total == 0:
        neg = (any_product and all_neg_zero) or mode == 'RDN'
        return {"bits": format((1 << (w - 1)) if neg else 0, 'x'), "flags": []}

    sgn = 1 if total < 0 else 0
    x = -total if sgn else total
    L = _floorlog2(x)
    qe = max(emin - fbits, L - fbits)
    q = Fraction(2) ** qe
    t = x / q
    n = t.numerator // t.denominator
    r = t - n
    inexact = r != 0
    half = Fraction(1, 2)
    if inexact:
        if mode == 'RNE':
            if r > half or (r == half and n % 2 == 1):
                n += 1
        elif mode == 'RNA':
            if r >= half:
                n += 1
        elif mode == 'RUP':
            if sgn == 0:
                n += 1
        elif mode == 'RDN':
            if sgn == 1:
                n += 1
    y = n * q

    if y >= Fraction(2) ** (emax + 1):
        flags = ["overflow", "inexact"]
        if mode in ("RNE", "RNA") or (mode == "RUP" and sgn == 0) or (mode == "RDN" and sgn == 1):
            return {"bits": format((sgn << (w - 1)) | (Eall << fbits), 'x'), "flags": flags}
        return {"bits": format((sgn << (w - 1)) | ((Eall - 1) << fbits) | fmask, 'x'), "flags": flags}

    flags = []
    if inexact:
        if y < Fraction(2) ** emin:
            flags.append("underflow")
        flags.append("inexact")

    if y == 0:
        bits = sgn << (w - 1)
    else:
        Ly = _floorlog2(y)
        if Ly >= emin:
            e_field = Ly + bias
            sig = y / (Fraction(2) ** (Ly - fbits))
            assert sig.denominator == 1, req
            sig = sig.numerator
            assert F <= sig < 2 * F, req
            bits = (sgn << (w - 1)) | (e_field << fbits) | (sig & fmask)
        else:
            ff = y / (Fraction(2) ** (emin - fbits))
            assert ff.denominator == 1, req
            ff = ff.numerator
            assert 0 < ff < F, req
            bits = (sgn << (w - 1)) | ff
    return {"bits": format(bits, 'x'), "flags": flags}
