import random, struct, sys
from fractions import Fraction
from main import solve

def f2bits(f):
    return struct.unpack('>Q', struct.pack('>d', f))[0]

def bits2f(v):
    return struct.unpack('>d', struct.pack('>Q', v))[0]

random.seed(999)
MIN_NORM = Fraction(2) ** -1022
bad = 0

def check64(pairs_hex):
    req = {"ebits": 11, "fbits": 52, "mode": "RNE", "pairs": pairs_hex}
    got = solve(req)
    gb = int(got["bits"], 16)
    # exact sum
    total = Fraction(0)
    for a, c in pairs_hex:
        total += Fraction(bits2f(int(a, 16))) * Fraction(bits2f(int(c, 16)))
    try:
        ef = float(total)
        eb = f2bits(ef)
        of = False
    except OverflowError:
        ef = None
        eb = (1 if total < 0 else 0) << 63 | (0x7ff << 52)
        of = True
    if eb != gb:
        print("BITS MISMATCH", req, hex(gb), hex(eb))
        return False
    # flags
    exp_flags = []
    if of:
        exp_flags = ["overflow", "inexact"]
    else:
        inex = Fraction(ef) != total
        if inex:
            if abs(Fraction(ef)) < MIN_NORM:
                exp_flags.append("underflow")
            exp_flags.append("inexact")
    if set(got["flags"]) != set(exp_flags):
        print("FLAGS MISMATCH", req, got["flags"], exp_flags)
        return False
